buggyCode:
record Event(String name, long createdAt) {}

long day = 86_400_000L;
long now = 1_790_000_000_000L;
List<Event> events = new ArrayList<>(List.of(
    new Event("A", now - 30 * day),
    new Event("B", now),
    new Event("C", now - 10 * day)));

events.sort((x, y) -> (int) (x.createdAt() - y.createdAt()));
System.out.println(events.stream().map(Event::name).toList());

fix.code:
events.sort(Comparator.comparingLong(Event::createdAt));

// Hoặc tự viết:
events.sort((x, y) -> Long.compare(x.createdAt(), y.createdAt()));
